      "proposed_laureates": [
        "Chang C. Tsuei",
        "Dale J. Van Harlingen",
        "John R. Kirtley"
      ],
      "assessment": {
        "nobel_worthiness": "Phase-sensitive experiments established d-wave pairing in cuprates, resolving a central question about the mechanism and symmetry of high-temperature superconductivity. The result is a clear, consequential experimental discovery.",
        "attribution": "The credited researchers made closely related phase-sensitive contributions; the award would need to distinguish their respective experimental roles and account for other groups' work.",
        "maturity": "The evidence has stood for decades and is foundational to the field's understanding of cuprates.",
        "uncertainties": [
          "The discovery is important, though its scope may be judged narrower than a prize recognizing superconductivity itself."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise full-sky mapping of the cosmic microwave background established a quantitative era of precision cosmology and strongly constrained the universe's composition and history.",
        "attribution": "Bennett and Page were central to the mission and its measurements; Spergel made major contributions to interpreting the results. Credit should reflect the broad team effort and the earlier COBE foundation.",
        "maturity": "The measurements and their cosmological conclusions have been extensively checked and built upon by later observations.",
        "uncertainties": [
          "The division of credit between WMAP, COBE, and later CMB experiments requires careful framing."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks enabled a major leap in precision timekeeping, with consequences for tests of fundamental physics, geodesy, and future time standards.",
        "attribution": "Katori and Ye led distinct, complementary approaches that established the field; the shared recognition is well supported.",
        "maturity": "The clocks are now mature instruments with repeatedly demonstrated accuracy and systematic control.",
        "uncertainties": [
          "The prize case depends on weighing a transformative measurement technology against its still-developing reach in fundamental discovery."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light overcame a quantum noise limit in interferometry and became an important tool for gravitational-wave detection, linking foundational quantum optics to a landmark observational capability.",
        "attribution": "Caves provided key theoretical foundations, Kimble advanced experimental squeezed-light methods, and Mavalvala helped bring the technique into gravitational-wave observatories.",
        "maturity": "Squeezing has been implemented in operating gravitational-wave detectors and its benefits measured directly.",
        "uncertainties": [
          "The field includes substantial contributions from additional researchers, and the prize scope must distinguish the central advance from broader interferometer development."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite decoherence and supplied essential concepts for fault-tolerant quantum computation. The work changed the prospects and language of the field.",
        "attribution": "Shor and Steane introduced influential early codes, while Kitaev developed topological approaches with deep consequences for fault tolerance. Their contributions are complementary but not identical.",
        "maturity": "The theory is established and experimental demonstrations have advanced, although large-scale fault-tolerant quantum computing remains unrealized.",
        "uncertainties": [
          "The ultimate practical impact of quantum computing is not yet known.",
          "Many later contributions shaped the subject, so the precise discovery boundary needs care."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "AdS/CFT is a striking gauge-gravity duality that has reshaped theoretical physics and created powerful links among gravity, quantum field theory, and strongly coupled systems.",
        "attribution": "Maldacena's conjecture was the decisive formulation; Witten clarified and extended its meaning. Earlier holographic ideas, including Polyakov's, form important context for attribution.",
        "maturity": "The duality has survived extensive theoretical development and applications, but direct empirical confirmation of its relevance to our universe is lacking.",
        "uncertainties": [
          "Its status as a physical discovery rather than a mathematically powerful conjecture remains open.",
          "The known anti-de Sitter setting differs from the observed cosmological setting."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers an influential account of the universe's early expansion, while quantum fluctuations provide a compelling origin for the structures later observed in the cosmos.",
        "attribution": "Guth and Linde developed influential inflationary scenarios; Mukhanov made foundational contributions to the theory of cosmological perturbations. The proposed credit spans related but distinguishable advances.",
        "maturity": "The framework is compatible with many observations, but no distinctive inflationary signal has yet established a unique model.",
        "uncertainties": [
          "Inflation has many variants with different predictions, making the claim and attribution difficult to delimit.",
          "The quantum origin of structure is strongly supported as a framework but not directly established in a model-specific way."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Edo Berger"
      ],
      "assessment": {
        "nobel_worthiness": "Kilonova observations connected neutron-star mergers to heavy-element production and demonstrated the power of multi-messenger astronomy. This is an important advance in astrophysics and nuclear astrophysics.",
        "attribution": "Metzger and Kasen made influential theoretical predictions and modeling contributions; Berger contributed to observational work. The broader discovery involved many observers and theorists.",
        "maturity": "The neutron-star merger association is well established, while the detailed accounting of r-process yields continues to develop.",
        "uncertainties": [
          "The amount and distribution of heavy elements produced in mergers remain under study.",
          "The breadth of the collaboration and the separation of prediction, observation, and interpretation complicate individual attribution."
        ]
      }
    }
  ]
